export const getSearchModelsUrl = (params: SearchModelsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/models/search?${stringifiedParams}` : `/api/models/search`
}

/**
 * @summary Fuzzy search Hot Wheels model database
 */
export const searchModels = async (params: SearchModelsParams, options?: RequestInit): Promise<ModelSuggestion[]> => {

  return customFetch<ModelSuggestion[]>(getSearchModelsUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getSearchModelsQueryKey = (params?: SearchModelsParams,) => {
    return [
    `/api/models/search`, ...(params ? [params] : [])
    ] as const;
    }


export const getSearchModelsQueryOptions = <TData = Awaited<ReturnType<typeof searchModels>>, TError = ErrorType<unknown>>(params: SearchModelsParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof searchModels>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getSearchModelsQueryKey(params);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof searchModels>>> = ({ signal }) => searchModels(params, { signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof searchModels>>, TError, TData> & { queryKey: QueryKey }
}

export type SearchModelsQueryResult = NonNullable<Awaited<ReturnType<typeof searchModels>>>
export type SearchModelsQueryError = ErrorType<unknown>


/**
 * @summary Fuzzy search Hot Wheels model database
 */

export function useSearchModels<TData = Awaited<ReturnType<typeof searchModels>>, TError = ErrorType<unknown>>(
 params: SearchModelsParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof searchModels>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getSearchModelsQueryOptions(params,options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return { ...query, queryKey: queryOptions.queryKey };
}







